SELECT
ga.*,
gc.plan_no AS plan_no,
sat.abnormal_name AS abnormal_name,
sa.area_name AS area_name,
su.user_name AS report_name
FROM garbage_abnormal ga
LEFT JOIN garbage_collection gc ON ga.plan_id = gc.plan_no AND gc.deleted = 0
LEFT JOIN sys_abnormal_type sat ON ga.abnormal_type_id = sat.abnormal_type_id AND sat.deleted = 0
LEFT JOIN sys_area sa ON ga.area_code = sa.area_code AND sa.deleted = 0
LEFT JOIN sys_user su ON ga.report_by = su.user_id AND su.deleted = 0
WHERE ga.deleted = 0


    AND ga.abnormal_id = #{reqVO.abnormalId}


    AND ga.plan_id = #{reqVO.planId}


    AND ga.abnormal_type_id = #{reqVO.abnormalTypeId}


    AND ga.area_code = #{reqVO.areaCode}


    AND ga.report_by = #{reqVO.reportBy}



    AND ga.report_time BETWEEN #{reqVO.reportTime[0]} AND #{reqVO.reportTime[1]}


    AND ga.priority = #{reqVO.priority}


    AND ga.handler_id = #{reqVO.handlerId}


    AND ga.handle_status = #{reqVO.handleStatus}


    AND ga.is_timeout = #{reqVO.isTimeout}


    AND ga.review_status = #{reqVO.reviewStatus}


    AND ga.review_by = #{reqVO.reviewBy}



    AND ga.review_time BETWEEN #{reqVO.reviewTime[0]} AND #{reqVO.reviewTime[1]}



    AND ga.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

ORDER BY ga.id DESC
LIMIT #{reqVO.offset}, #{reqVO.limit}

